arguments.content:
:root{
  --paper:#fff7e8; --paper2:#ffefcd; --ink:#182233; --ink2:#46536a;
  --coral:#ff5c39; --coral-d:#e8431f; --teal:#0e7c6b; --sun:#ffb627; --sun2:#ffd166;
  --violet:#6c5ce7; --card:#fffdf7; --line:#ead9b8; --night:#10182b; --night2:#18233d;
  --radius:22px; --shadow:0 18px 45px rgba(24,34,51,.13);
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{background:var(--paper);color:var(--ink);font-family:ui-sans-system,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;line-height:1.55;-webkit-font-smoothing:antialiased;overflow-x:hidden}
h1,h2,h3{font-family:ui-serif,Georgia,"Times New Roman",serif;line-height:1.02;letter-spacing:-.02em}
a{color:inherit}
button{font:inherit;cursor:pointer}
.hidden{display:none!important}

/* topbar */
.topbar{position:fixed;inset:0 0 auto 0;z-index:50;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 22px;background:rgba(255,247,232,.88);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.brand{display:flex;gap:9px;align-items:center;text-decoration:none;font-weight:900;letter-spacing:.06em;font-size:14px}
.brand em{font-family:ui-serif,Georgia,serif;text-transform:none;letter-spacing:0;color:var(--coral);font-size:17px}
.brand-dot{width:26px;height:26px;border-radius:50%;background:radial-gradient(circle at 35% 35%,var(--sun2),var(--coral) 65%);box-shadow:0 0 0 4px #ffe3b3}
.journey{display:flex;align-items:center;gap:9px;font-size:11px;font-weight:800;letter-spacing:.08em;color:var(--ink2)}
.lights{display:flex;gap:5px}
.lights i{width:13px;height:13px;border-radius:50%;border:2px solid #d9c491;background:transparent;transition:.4s}
.lights i.on{background:var(--sun);border-color:var(--sun);box-shadow:0 0 10px var(--sun2)}
.top-cta{text-decoration:none;font-weight:800;font-size:13px;background:var(--ink);color:#fff;padding:9px 15px;border-radius:999px;white-space:nowrap}
.top-cta:hover{background:var(--coral)}

/* hero */
.hero{position:relative;min-height:100svh;display:flex;align-items:center;padding:130px 6vw 90px;overflow:hidden;background:radial-gradient(1000px 600px at 85% 20%,#ffe9ad 0,transparent 55%),radial-gradient(800px 500px at 0 90%,#ffd9c9 0,transparent 50%),var(--paper)}
#globe{position:absolute;right:-4vw;top:50%;transform:translateY(-50%);width:min(62vw,760px);height:min(62vw,760px);opacity:.95;pointer-events:none}
.hero-copy{position:relative;z-index:2;max-width:680px}
.eyebrow{font-size:11px;font-weight:900;letter-spacing:.16em;display:flex;gap:9px;align-items:center;color:var(--ink2)}
.pulse{width:9px;height:9px;border-radius:50%;background:var(--teal);animation:pulse 2s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(14,124,107,.4)}70%{box-shadow:0 0 0 9px transparent}100%{box-shadow:0 0 0 0 transparent}}
.hero h1{font-size:clamp(52px,8.5vw,108px);margin:22px 0 20px;font-weight:900}
.highlight{color:var(--coral);background:linear-gradient(transparent 62%,#ffd166 62%);padding:0 .08em}
.lede{font-size:clamp(19px,2.3vw,25px);line-height:1.45;max-width:600px}
.lede strong{color:var(--teal)}
.lede-small{margin-top:14px;color:var(--ink2);font-size:16px;max-width:540px}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap;margin:30px 0 34px}
.btn{border:0;border-radius:999px;padding:14px 24px;font-weight:850;font-size:15px;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;transition:transform .15s,box-shadow .15s,background .15s}
.btn:active{transform:scale(.97)}
.btn-primary{background:var(--coral);color:#fff;box-shadow:0 10px 24px rgba(255,92,57,.35)}
.btn-primary:hover{background:var(--coral-d);transform:translateY(-2px)}
.btn-ghost{background:#fff;color:var(--ink);border:2px solid var(--ink)}
.btn-ghost:hover{border-color:var(--coral);color:var(--coral)}
.btn-dark{background:var(--ink);color:#fff}.btn-dark:hover{background:var(--teal)}
.btn-sun{background:var(--sun);color:var(--ink);box-shadow:0 10px 24px rgba(255,182,39,.4)}
.btn-sun:hover{background:var(--sun2);transform:translateY(-2px)}
.btn-big{font-size:17px;padding:17px 30px}.btn-small{padding:9px 16px;font-size:13px}
.hero-stats{list-style:none;display:flex;gap:34px;flex-wrap:wrap}
.hero-stats li{display:flex;flex-direction:column}
.hero-stats strong{font-family:ui-serif,Georgia,serif;font-size:30px}
.hero-stats span{font-size:11px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:var(--ink2)}
.hero-card{position:absolute;right:5vw;bottom:110px;z-index:2;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px 18px;max-width:280px;box-shadow:var(--shadow);transform:rotate(2deg)}
.hero-card-tag{font-size:10px;font-weight:900;letter-spacing:.14em;color:var(--coral)}
.hero-card p{font-family:ui-serif,Georgia,serif;font-size:19px;line-height:1.3;margin:7px 0}
.hero-card-foot{font-size:12px;color:var(--ink2);display:flex;gap:7px;align-items:center}
.hero-card-foot i{width:7px;height:7px;border-radius:50%;background:var(--teal)}
.scroll-hint{position:absolute;left:6vw;bottom:26px;font-size:11px;font-weight:900;letter-spacing:.2em;text-transform:uppercase;color:var(--ink2);text-decoration:none;display:flex;gap:10px;align-items:center}
.scroll-hint span{width:1px;height:38px;background:var(--ink2);display:block;animation:drop 1.8s infinite}
@keyframes drop{0%{transform:scaleY(0);transform-origin:top}50%{transform:scaleY(1)}100%{transform:scaleY(0);transform-origin:bottom}}

/* strip */
.strip{background:var(--ink);color:#fff;padding:44px 6vw;text-align:center}
.strip p{font-family:ui-serif,Georgia,serif;font-size:clamp(20px,3vw,30px);max-width:980px;margin:auto;line-height:1.4}
.strip span{color:var(--sun2)} .strip em{color:#ffb59f}

/* sections */
.section{padding:100px 6vw;max-width:1360px;margin:auto}
.section-head{display:flex;gap:22px;align-items:flex-start;margin-bottom:44px}
.num{font-family:ui-serif,Georgia,serif;font-size:54px;color:transparent;-webkit-text-stroke:2px var(--coral);line-height:.9;flex:none}
.kicker{font-size:11px;font-weight:900;letter-spacing:.18em;color:var(--coral);margin-bottom:8px}
.kicker.light{color:var(--sun)}
.section h2{font-size:clamp(34px,4.6vw,56px);font-weight:900;max-width:700px}
.section-lede{margin-top:14px;color:var(--ink2);font-size:17px;max-width:660px}
.fineprint{font-size:12px;color:var(--ink2);margin-top:18px;max-width:760px}

/* village */
.village-layout{display:grid;grid-template-columns:1.35fr .85fr;gap:26px;align-items:start}
.village-card,.fact-detail,.life-card,.quiz-card,.mission-card,.ripple-card,.plan-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}
.village-card{padding:26px}
.people-grid{display:grid;grid-template-columns:repeat(10,1fr);gap:clamp(6px,1.2vw,12px)}
.person{aspect-ratio:1;border-radius:50%;background:#e7dcc4;transition:background .3s,transform .3s;position:relative}
.person.on{background:radial-gradient(circle at 35% 30%,var(--sun2),var(--sun) 70%)}
.person.on.teal{background:radial-gradient(circle at 35% 30%,#5fd0bd,var(--teal) 70%)}
.person.on.coral{background:radial-gradient(circle at 35% 30%,#ffab91,var(--coral) 70%)}
.person.pop{transform:scale(1.35)}
.village-caption{display:flex;gap:20px;flex-wrap:wrap;margin-top:20px;font-size:12px;font-weight:700;color:var(--ink2);align-items:center}
.legend{display:flex;gap:7px;align-items:center}.sw{width:14px;height:14px;border-radius:50%;display:inline-block}
.sw-on{background:var(--sun)} .sw-off{background:#e7dcc4}
.village-note{margin-left:auto}
.fact-tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}
.chip{border:2px solid var(--line);background:#fff;border-radius:999px;padding:9px 15px;font-weight:800;font-size:13px;transition:.15s}
.chip:hover{border-color:var(--ink)}
.chip.active{background:var(--ink);color:#fff;border-color:var(--ink)}
.fact-detail{padding:26px;margin-bottom:16px}
.fact-big{font-family:ui-serif,Georgia,serif;font-size:76px;line-height:1;color:var(--ink)}
.fact-big small{font-size:22px;color:var(--ink2)}
.fact-text{font-size:17px;margin:10px 0}
.fact-hope{background:#e9f6f2;border-left:4px solid var(--teal);padding:12px 14px;border-radius:0 12px 12px 0;font-size:14px}
.fact-source{font-size:11px;color:var(--ink2);margin-top:12px;letter-spacing:.04em}

/* life */
.section-life{background:linear-gradient(180deg,var(--paper),#ffeedd);max-width:none}
.section-life>*{max-width:1232px;margin-left:auto;margin-right:auto}
.section-life .section-head{margin-bottom:44px}
.life-layout{display:grid;grid-template-columns:1.25fr .75fr;gap:26px;align-items:start}
.life-card{padding:30px;transition:transform .3s}
.life-card.shake{animation:shake .45s}
@keyframes shake{0%,100%{transform:translateX(0)}25%{transform:translateX(-7px) rotate(-.4deg)}75%{transform:translateX(7px) rotate(.4deg)}}
.life-top{display:flex;gap:16px;align-items:center;border-bottom:1px dashed var(--line);padding-bottom:18px}
.avatar{width:64px;height:64px;border-radius:50%;background:var(--teal);color:#fff;display:grid;place-items:center;font-family:ui-serif,Georgia,serif;font-size:30px;flex:none}
.life-top h3{font-size:30px}.life-top p{color:var(--ink2);font-size:14px}
.life-badge{margin-left:auto;font-size:10px;font-weight:900;letter-spacing:.12em;background:#fff0c9;padding:7px 10px;border-radius:999px;white-space:nowrap}
.life-rows p{display:grid;grid-template-columns:190px 1fr;gap:14px;padding:13px 0;border-bottom:1px dashed #f0e3c8;font-size:15px}
.life-rows span{font-size:10px;font-weight:900;letter-spacing:.12em;color:var(--coral);padding-top:4px}
.life-rows b{font-weight:650}
.shared{margin-top:18px;background:#10182b;color:#fff;border-radius:16px;padding:20px 22px}
.shared-title{font-family:ui-serif,Georgia,serif;font-size:21px;color:var(--sun2)}
.shared ul{margin:10px 0 10px 20px}.shared li{margin:5px 0}
.shared-foot{font-size:13px;color:#c6cfe2}
.life-side blockquote{font-family:ui-serif,Georgia,serif;font-size:20px;line-height:1.4;margin-top:24px;padding-left:18px;border-left:4px solid var(--sun)}
.life-side blockquote cite{display:block;font-family:ui-sans-system,system-ui,sans-serif;font-size:12px;color:var(--ink2);margin-top:8px;font-style:normal}
.life-count{margin:16px 0;font-size:15px}
.empathy-meter{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px}
.empathy-head{display:flex;justify-content:space-between;font-size:11px;font-weight:900;letter-spacing:.1em}
.empathy-head b{color:var(--teal);letter-spacing:0;font-size:13px}
.meter{height:12px;background:#f0e3c8;border-radius:99px;overflow:hidden;margin:12px 0}
.meter i{display:block;height:100%;width:4%;background:linear-gradient(90deg,var(--sun),var(--coral));border-radius:99px;transition:width .8s cubic-bezier(.2,.8,.2,1)}
.empathy-meter p{font-size:13px;color:var(--ink2)}

/* quiz */
.ground-layout{display:grid;grid-template-columns:1.25fr .75fr;gap:26px;align-items:start}
.quiz-card{padding:30px}
.quiz-progress{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:11px;font-weight:900;letter-spacing:.1em;color:var(--ink2);margin-bottom:18px}
.quiz-card h3{font-size:22px;color:var(--ink2);font-family:ui-sans-system,system-ui,sans-serif;letter-spacing:0;font-weight:750}
.quiz-statement{font-family:ui-serif,Georgia,serif;font-size:clamp(24px,3vw,34px);line-height:1.25;margin:12px 0 26px}
.slider-row{display:flex;gap:16px;align-items:center}
input[type=range]{-webkit-appearance:none;appearance:none;flex:1;height:10px;border-radius:99px;background:linear-gradient(90deg,var(--sun),var(--coral));outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:30px;height:30px;border-radius:50%;background:#fff;border:3px solid var(--ink);box-shadow:0 4px 12px rgba(0,0,0,.25);cursor:grab}
input[type=range]::-moz-range-thumb{width:28px;height:28px;border-radius:50%;background:#fff;border:3px solid var(--ink);cursor:grab}
.slider-row output{font-family:ui-serif,Georgia,serif;font-size:30px;min-width:78px;text-align:right}
.bar-wrap{margin-top:24px;background:#fff7e8;border-radius:14px;padding:18px}
.bar-row{display:grid;grid-template-columns:110px 1fr 52px;gap:12px;align-items:center;margin:9px 0;font-size:10px;font-weight:900;letter-spacing:.08em}
.bar{height:16px;background:#eadfc6;border-radius:99px;overflow:hidden}
.bar i{display:block;height:100%;width:0;transition:width .9s cubic-bezier(.2,.8,.2,1)}
.bar-you i{background:var(--violet)} .bar-real i{background:var(--teal)}
.bar-row b{font-size:15px}
.quiz-note{font-size:14px;margin-top:10px}
.quiz-actions{display:flex;gap:10px;margin-top:22px;flex-wrap:wrap}
.ground-side{padding-top:8px}
.big-agree{display:flex;flex-direction:column;margin-bottom:18px}
.big-agree strong{font-family:ui-serif,Georgia,serif;font-size:84px;color:var(--teal);line-height:1}
.big-agree span{color:var(--ink2);font-size:14px;max-width:280px}
.ground-side>p{color:var(--ink2);margin-bottom:16px}
.ground-callout{background:#e9f6f2!important;color:var(--ink)!important;padding:18px;border-radius:16px;font-size:16px}

/* breathe */
.section-breathe{max-width:none;background:radial-gradient(700px 400px at 50% 0,#24365f,transparent),var(--night);color:#fff;text-align:center}
.breathe-inner{max-width:760px;margin:auto}
.section-breathe h2{font-size:clamp(30px,4.4vw,50px)}
.breath-stage{display:grid;place-items:center;padding:52px 0 34px}
.breath-ring{width:230px;height:230px;border-radius:50%;background:radial-gradient(circle at 40% 35%,var(--sun2),var(--coral) 72%);display:grid;place-items:center;font-family:ui-serif,Georgia,serif;font-size:30px;color:var(--ink);box-shadow:0 0 80px rgba(255,182,39,.35);transition:transform 4s ease-in-out}
.breath-ring.in{transform:scale(1.28)} .breath-ring.out{transform:scale(.92);transition-duration:6s}
.breath-sub{color:#c6cfe2;max-width:520px;margin:auto}
.breath-controls{margin-top:26px;display:flex;flex-direction:column;gap:16px;align-items:center}
.breath-stats{font-size:13px;color:#c6cfe2}.breath-stats strong{color:#fff}

/* mission */
.mission-controls{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:22px}
.control-group>span{font-size:11px;font-weight:900;letter-spacing:.14em;color:var(--ink2);display:block;margin-bottom:10px}
.chips{display:flex;gap:8px;flex-wrap:wrap}
.mission-layout{display:grid;grid-template-columns:1.25fr .75fr;gap:26px;align-items:start}
.mission-card{padding:30px;border-top:6px solid var(--coral)}
.mission-top{display:flex;justify-content:space-between;font-size:11px;font-weight:900;letter-spacing:.12em}
.mission-tag{color:var(--coral)} .mission-time{color:var(--ink2)}
.mission-card h3{font-size:clamp(26px,3.2vw,36px);margin:14px 0 10px}
.mission-card>p{color:var(--ink2)}
.mission-steps{margin:18px 0 18px 22px;display:grid;gap:9px;font-size:15px}
.mission-steps li::marker{color:var(--coral);font-weight:900}
.timer{display:flex;align-items:center;gap:16px;background:var(--night);color:#fff;border-radius:14px;padding:14px 18px;margin:16px 0}
.timer span{font-family:ui-serif,Georgia,serif;font-size:34px;min-width:96px}
.mission-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}
.mission-accepted{background:#e9f6f2;padding:14px 16px;border-radius:12px;margin-top:16px;font-size:14px;color:var(--ink)!important}
.ripple-card{padding:26px;background:var(--ink);color:#fff;border-color:var(--ink)}
.ripple-card h3{font-size:26px;margin-bottom:8px}.ripple-card p{color:#c6cfe2;font-size:14px}
.ripple-card input{margin:20px 0 8px;width:100%}
.ripple-big strong{font-family:ui-serif,Georgia,serif;font-size:36px;color:var(--sun2)}
.ripple-list{list-style:none;margin-top:16px;display:grid;gap:12px}
.ripple-list li{display:flex;flex-direction:column;border-top:1px solid #2b3854;padding-top:10px}
.ripple-list b{font-size:21px;color:#fff}.ripple-list span{font-size:12px;color:#9fb0cf}
.ripple-card .fineprint{color:#9fb0cf}
.garden{margin-top:26px;background:#17351f;border-radius:var(--radius);padding:24px;color:#eaffef;overflow:hidden}
.garden-head{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;align-items:baseline}
.garden-head h3{font-size:24px}.garden-head span{font-size:13px;color:#a9d8b2}
.garden-bed{min-height:110px;display:flex;align-items:flex-end;gap:6px;flex-wrap:wrap;padding-top:18px;border-bottom:8px solid #0d2414}
.garden-empty{color:#a9d8b2;font-size:14px;padding-bottom:16px}
.flower{font-size:30px;line-height:1;animation:grow .7s cubic-bezier(.2,1.6,.4,1);transform-origin:bottom}
@keyframes grow{from{transform:scale(0) translateY(12px)}to{transform:scale(1) translateY(0)}}

/* light */
.section-light{max-width:none;background:linear-gradient(180deg,var(--night),#0a1020);color:#fff}
.section-light>*{max-width:1232px;margin-left:auto;margin-right:auto}
.num-light{-webkit-text-stroke-color:var(--sun)}
.light-lede{color:#c6cfe2!important}
.word-chips{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:22px}
.word-chips .chip{background:transparent;color:#fff;border-color:#35466a}
.word-chips .chip.active{background:var(--sun);color:var(--ink);border-color:var(--sun)}
.constellation-wrap{position:relative;text-align:center}
#constellation{width:100%;height:360px;display:block;background:radial-gradient(600px 260px at 50% 40%,#1d2c4e,transparent);border:1px solid #26365c;border-radius:var(--radius)}
.light-btn{margin-top:-28px;position:relative;z-index:2}
.light-count{margin-top:14px;color:#c6cfe2;font-size:14px}.light-count strong{color:#fff}
.plan-card{margin-top:38px;padding:28px;color:var(--ink)}
.plan-card h3{font-size:26px}.plan-card h3 span{font-family:ui-sans-system,system-ui,sans-serif;font-size:13px;color:var(--ink2);font-weight:600}
.plan-card p{margin:12px 0;font-size:17px;max-width:760px}
.plan-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}
.copy-note{font-size:13px;color:var(--teal);min-height:20px}

footer{padding:70px 6vw 90px;text-align:center;background:#0a1020;color:#fff}
.foot-big{font-family:ui-serif,Georgia,serif;font-size:clamp(22px,3.4vw,36px);line-height:1.35;max-width:900px;margin:auto}
.foot-big em{color:var(--sun2)}
.foot-small{margin-top:26px;font-size:11px;letter-spacing:.12em;color:#8fa0c0;font-weight:800}

.toast{position:fixed;left:50%;bottom:26px;transform:translateX(-50%) translateY(0);z-index:80;background:var(--ink);color:#fff;padding:14px 22px;border-radius:999px;font-weight:800;font-size:14px;box-shadow:var(--shadow);transition:.3s;max-width:90vw;text-align:center}
.toast.hidden{display:block!important;opacity:0;pointer-events:none;transform:translateX(-50%) translateY(16px)}

@media(max-width:900px){
  .village-layout,.life-layout,.ground-layout,.mission-layout,.mission-controls{grid-template-columns:1fr}
  #globe{opacity:.28;width:92vw;height:92vw;right:-30vw}
  .hero-card{display:none}
  .journey-label{display:none}
  .life-rows p{grid-template-columns:1fr;gap:3px}
  .top-cta{display:none}
  .section{padding:70px 5vw}
}
@media(prefers-reduced-motion:reduce){*{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

// 8 Billion Neighbors — all state is in-memory only. Nothing is stored or sent anywhere.

const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const rand = (arr) => arr[Math.floor(Math.random() * arr.length)];
const fmt = (n) => new Intl.NumberFormat("en", { notation: "compact", maximumFractionDigits: 1 }).format(n);

/* ---------- journey progress ---------- */
const milestones = new Set();
function markJourney(key) {
  if (milestones.has(key)) return;
  milestones.add(key);
  const lights = $$("#journeyLights i");
  lights.forEach((l, i) => l.classList.toggle("on", i < milestones.size));
  $("#journeyCount").textContent = `${Math.min(milestones.size, 5)} / 5`;
  if (milestones.size === 5) toast("Journey complete — village, neighbor, ground, breath, action. Now go be someone's good day. 🌍");
}
let toastTimer;
function toast(msg) {
  const t = $("#toast");
  t.textContent = msg;
  t.classList.remove("hidden");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.add("hidden"), 4200);
}

/* ---------- hero globe (canvas dot sphere) ---------- */
(() => {
  const cv = $("#globe"), ctx = cv.getContext("2d");
  let W, H, mx = 0, my = 0, t = 0;
  const N = 950, pts = [];
  for (let i = 0; i < N; i++) {
    const y = 1 - (i / (N - 1)) * 2, r = Math.sqrt(1 - y * y), th = i * 2.399963;
    pts.push({ x: Math.cos(th) * r, y, z: Math.sin(th) * r, c: ["#ffb627", "#ff5c39", "#0e7c6b", "#182233"][i % 17 === 0 ? 1 : i % 23 === 0 ? 2 : i % 5 === 0 ? 3 : 0] });
  }
  function size() { const s = cv.getBoundingClientRect(); const d = Math.min(devicePixelRatio || 1, 2); W = s.width; H = s.height; cv.width = W * d; cv.height = H * d; ctx.setTransform(d, 0, 0, d, 0, 0); }
  size(); addEventListener("resize", size);
  addEventListener("pointermove", (e) => { mx = (e.clientX / innerWidth - .5); my = (e.clientY / innerHeight - .5); });
  (function draw() {
    t += 0.0022;
    ctx.clearRect(0, 0, W, H);
    const R = Math.min(W, H) * 0.42, cx = W / 2, cy = H / 2;
    const rotY = t + mx * 1.4, rotX = my * 0.7;
    for (const p of pts) {
      let { x, y, z } = p;
      let x1 = x * Math.cos(rotY) - z * Math.sin(rotY), z1 = x * Math.sin(rotY) + z * Math.cos(rotY);
      let y1 = y * Math.cos(rotX) - z1 * Math.sin(rotX), z2 = y * Math.sin(rotX) + z1 * Math.cos(rotX);
      const a = 0.18 + 0.82 * Math.max(0, (z2 + 1) / 2);
      ctx.globalAlpha = a; ctx.fillStyle = p.c;
      ctx.beginPath(); ctx.arc(cx + x1 * R, cy + y1 * R, 1.4 + a * 2.1, 0, 7); ctx.fill();
    }
    ctx.globalAlpha = 1;
    requestAnimationFrame(draw);
  })();
})();

