import puppeteer from "puppeteer-core";
const browser = await puppeteer.launch({ executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", headless: "new", args: ["--no-sandbox"] });
const page = await browser.newPage();
page.on("console", m => console.log("CONSOLE", m.type(), m.text()));
page.on("pageerror", e => console.log("PAGEERROR", e.message));
await page.setViewport({ width: 390, height: 844, deviceScaleFactor: 1 });
await page.goto("http://localhost:8471/", { waitUntil: "networkidle0" });
const diag = await page.evaluate(() => {
  const bad = [];
  document.querySelectorAll("*").forEach(el => { const r = el.getBoundingClientRect(); if (r.right > innerWidth + 2 || r.left < -2) bad.push([el.tagName + "." + el.className, Math.round(r.left), Math.round(r.right), Math.round(r.width)]); });
  return { innerWidth, docW: document.documentElement.scrollWidth, bad: bad.slice(0, 20) };
});
console.log(JSON.stringify(diag, null, 1));
await page.screenshot({ path: "m-hero.jpg", type: "jpeg", quality: 82 });

// interact: meet a neighbor + share, quiz reveal, mission accept+done, light
await page.click("#lifeBtn"); await page.click("#shareBtn");
await page.evaluate(() => document.querySelector("#village").scrollIntoView());
await new Promise(r => setTimeout(r, 600));
await page.screenshot({ path: "m-village.jpg", type: "jpeg", quality: 82 });
await page.setViewport({ width: 1280, height: 950 });
await page.evaluate(() => document.querySelector("#life").scrollIntoView());
await new Promise(r => setTimeout(r, 600));
await page.screenshot({ path: "d-life.jpg", type: "jpeg", quality: 82 });
await page.click("#quizCheck");
await page.evaluate(() => document.querySelector("#mission").scrollIntoView());
await new Promise(r => setTimeout(r, 500));
await page.click("#acceptMission"); await page.click("#doneMission");
await new Promise(r => setTimeout(r, 500));
await page.screenshot({ path: "d-mission.jpg", type: "jpeg", quality: 82 });
await page.click("#lightBtn");
await page.evaluate(() => document.querySelector("#breathe").scrollIntoView());
await new Promise(r => setTimeout(r, 500));
await page.screenshot({ path: "d-breathe.jpg", type: "jpeg", quality: 82 });
const state = await page.evaluate(() => ({ journey: document.querySelector("#journeyCount").textContent, garden: document.querySelector("#gardenCount").textContent, lives: document.querySelector("#lifeCount").textContent, plan: document.querySelector("#planText").textContent, quizNote: document.querySelector("#quizNote").textContent.slice(0, 60) }));
console.log("STATE", JSON.stringify(state, null, 1));
await browser.close();

